<script setup lang="ts">
import {ref,reactive} from 'vue';
import {catalogOptions,type CatalogOption} from '../services/metadata';
import {catalogFilters,applyCatalogFilters} from '../stores/catalogFilters';
const options=reactive<Record<string,CatalogOption[]>>({}),chosen=reactive<Record<string,string[]>>({}),numbers=reactive<Record<string,string>>({}),flags=reactive({include_descendants:true,size_unknown:false,rating_unknown:false,technical_unknown:false}),purchaseCurrency=ref(''),availability=ref(''),favorite=ref(''),busy=ref(false),error=ref('');
const fields=[['group_ids','그룹','groups'],['package_ids','패키지','packages'],['types','유형 분류','types'],['creator_ids','제작 주체','creators'],['tags','사용자 태그','tags'],['formats','파일 형식','formats'],['roles','분류 역할','facets','role'],['styles','스타일','facets','style'],['genres','장르','facets','genre'],['views','시점','facets','view'],['dimensions','차원','facets','dimension'],['engines','선언 엔진','facets','engine'],['license_labels','라이선스명','license_labels']] as const;
const ranges=[['size','가용한 고유 연결 파일 합계 바이트'],['rating','사용자 평점 1~5'],['width','연결 파일 최대 가로'],['height','연결 파일 최대 세로'],['duration','연결 파일 최대 길이(ms)']] as const;
const extra=[['purchase_status','구매 금액 상태(선언)',[['unknown','미확인'],['free','무료(0)'],['paid','유료']]],['creator_roles','제작 역할',[['creator','제작자'],['producer','제작사'],['distributor','배포사']]],['license_status','사용자 라이선스 검토 상태',[['unknown','미확인'],['needs_review','검토 필요'],['user_reviewed','사용자가 검토함']]],['management_states','관리 상태',[['unreviewed','미검토'],['reviewing','검토 중'],['approved','사용자 관리 승인'],['archived','보관']]]] as const;
function restore(){purchaseCurrency.value=String(catalogFilters.value.purchase_currency??'');for(const [key] of [...fields,...extra])chosen[key]=Array.isArray(catalogFilters.value[key])?[...(catalogFilters.value[key] as string[])]:[];for(const [key] of ranges)for(const side of ['min','max'])numbers[side+'_'+key]=String(catalogFilters.value[side+'_'+key]??'');Object.assign(flags,{include_descendants:catalogFilters.value.include_descendants!==false,size_unknown:catalogFilters.value.size_unknown===true,rating_unknown:catalogFilters.value.rating_unknown===true,technical_unknown:catalogFilters.value.technical_unknown===true});availability.value=String(catalogFilters.value.availability??'');favorite.value=catalogFilters.value.favorite===undefined?'':String(catalogFilters.value.favorite);}
restore();
async function load(){if(busy.value)return;busy.value=true;error.value='';try{const kinds=[...new Set(fields.map(f=>f[2]))];const data=await Promise.all(kinds.map(k=>catalogOptions(k)));kinds.forEach((k,i)=>{options[k]=data[i]!;});}catch{error.value='필터 선택 목록을 조회하지 못했습니다. 기존 선택은 유지됩니다.';}finally{busy.value=false;}}
function apply(){const value:Record<string,unknown>={};error.value='';for(const [key] of [...fields,...extra])if(chosen[key]?.length)value[key]=[...chosen[key]!];for(const [key] of ranges)for(const side of ['min','max']){const text=numbers[side+'_'+key];if(text!==''){const n=Number(text);if(!Number.isSafeInteger(n)||n<0){error.value='수치 범위를 정수로 확인하세요.';return;}value[side+'_'+key]=n;}}
 if(purchaseCurrency.value){if(!/^[A-Z]{3}$/.test(purchaseCurrency.value)){error.value='통화는 대문자 3자리 코드로 입력하세요.';return;}value.purchase_currency=purchaseCurrency.value;}if(!flags.include_descendants)value.include_descendants=false;for(const key of ['size_unknown','rating_unknown','technical_unknown'] as const)if(flags[key])value[key]=true;if(availability.value)value.availability=availability.value;if(favorite.value)value.favorite=favorite.value==='true';applyCatalogFilters(value);}
function clear(){applyCatalogFilters({});restore();}
</script>
<template><details class="advanced-filters"><summary>복합 필터</summary><p>같은 항목은 OR, 다른 항목은 AND로 적용합니다. 분류·라이선스·엔진 선언은 권리/호환성 검증이 아닙니다.</p><button type="button" :disabled="busy" @click="load">필터 선택 목록 조회</button><p v-if="error" role="alert">{{error}}</p>
 <form @submit.prevent="apply"><label v-for="field in fields" :key="field[0]">{{field[1]}}<select v-model="chosen[field[0]]" multiple><option v-if="field[0]!=='license_labels'" value="__unknown__">미확인 / 소속 없음</option><option v-for="o in (options[field[2]]??[]).filter(o=>!('3' in field)||o.axis===field[3])" :key="o.id" :value="o.id">{{o.name}}</option></select></label>
 <label v-for="[key,label,values] in extra" :key="key">{{label}}<select v-model="chosen[key]" multiple><option v-for="[id,name] in values" :key="id" :value="id">{{name}}</option></select></label>
 <label>구매 통화(현재 선언)<input v-model="purchaseCurrency" maxlength="3" placeholder="KRW" /></label><fieldset v-for="[key,label] in ranges" :key="key"><legend>{{label}}</legend><label>최소<input v-model="numbers['min_'+key]" type="number" min="0" step="1" /></label><label>최대<input v-model="numbers['max_'+key]" type="number" min="0" step="1" /></label></fieldset>
 <label><input v-model="flags.include_descendants" type="checkbox" />하위 분류·그룹 포함</label><label><input v-model="flags.size_unknown" type="checkbox" />크기 미확인 포함 (범위 없으면 미확인만)</label><label><input v-model="flags.rating_unknown" type="checkbox" />평점 미평가 포함 (범위 없으면 미평가만)</label><label><input v-model="flags.technical_unknown" type="checkbox" />관측 기술 정보 미확인 포함 (범위 없으면 관측값 없는 대상만)</label>
 <label>파일 가용성<select v-model="availability"><option value="">전체</option><option value="available">모두 가용</option><option value="partial">일부 누락</option><option value="missing">모두 누락</option></select></label><label>즐겨찾기<select v-model="favorite"><option value="">전체</option><option value="true">즐겨찾기만</option><option value="false">즐겨찾기 아님</option></select></label><button>복합 필터 적용</button><button type="button" @click="restore">필터 초안 취소</button><button type="button" @click="clear">복합 필터 해제</button></form></details></template>
